//! Minimal logger mimicking a "pretty" env-style logger.
//!
//! Filtering is configured through the `RUST_LOG` environment variable using
//! the familiar `target=level,level/regex` syntax.

use std::env;
use std::io::{self, IsTerminal, Write};
use std::sync::OnceLock;

use regex::Regex;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum LevelFilter {
    Off = 0,
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

impl LevelFilter {
    fn parse(s: &str) -> Option<LevelFilter> {
        const NAMES: [(&str, LevelFilter); 6] = [
            ("OFF", LevelFilter::Off),
            ("ERROR", LevelFilter::Error),
            ("WARN", LevelFilter::Warn),
            ("INFO", LevelFilter::Info),
            ("DEBUG", LevelFilter::Debug),
            ("TRACE", LevelFilter::Trace),
        ];
        NAMES
            .iter()
            .find(|(name, _)| name.eq_ignore_ascii_case(s))
            .map(|(_, lvl)| *lvl)
    }
}

struct Directive {
    name: Option<String>,
    level: LevelFilter,
}

struct Logger {
    directives: Vec<Directive>,
    regex: Option<Regex>,
    color: bool,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();

pub const TARGET: &str = "eureka";

fn parse_spec(spec: &str) -> (Vec<Directive>, Option<Regex>) {
    let mut dirs = Vec::new();

    let mut parts = spec.split('/');
    let mods = parts.next();
    let filter = parts.next();
    if parts.next().is_some() {
        eprintln!(
            "warning: invalid logging spec '{}', ignoring it (too many '/'s)",
            spec
        );
        return (dirs, None);
    }

    if let Some(m) = mods {
        for s in m.split(',').map(|ss| ss.trim()) {
            if s.is_empty() {
                continue;
            }
            let mut pieces = s.split('=');
            let first = pieces.next();
            let second = pieces.next().map(|p| p.trim());
            let third = pieces.next();
            let (level, name) = match (first, second, third) {
                (Some(part0), None, None) => match LevelFilter::parse(part0) {
                    Some(lvl) => (lvl, None),
                    None => (LevelFilter::Trace, Some(part0)),
                },
                (Some(part0), Some(""), None) => (LevelFilter::Trace, Some(part0)),
                (Some(part0), Some(part1), None) => match LevelFilter::parse(part1) {
                    Some(lvl) => (lvl, Some(part0)),
                    None => {
                        eprintln!("warning: invalid logging spec '{}', ignoring it", part1);
                        continue;
                    }
                },
                _ => {
                    eprintln!("warning: invalid logging spec '{}', ignoring it", s);
                    continue;
                }
            };
            dirs.push(Directive {
                name: name.map(|n| n.to_string()),
                level,
            });
        }
    }

    let regex = filter.and_then(|f| match Regex::new(f) {
        Ok(re) => Some(re),
        Err(e) => {
            eprintln!("warning: invalid regex filter - {}", e);
            None
        }
    });

    (dirs, regex)
}

fn build_directives(parsed: Vec<Directive>) -> Vec<Directive> {
    if parsed.is_empty() {
        return vec![Directive {
            name: None,
            level: LevelFilter::Error,
        }];
    }
    // Later directives for the same name replace earlier ones.
    let mut merged: Vec<Directive> = Vec::new();
    for d in parsed {
        if let Some(existing) = merged.iter_mut().find(|e| e.name == d.name) {
            existing.level = d.level;
        } else {
            merged.push(d);
        }
    }
    merged.sort_by_key(|d| d.name.as_ref().map(|n| n.len()).unwrap_or(0));
    merged
}

fn colors_allowed() -> bool {
    if !io::stderr().is_terminal() {
        return false;
    }
    match env::var_os("TERM") {
        None => return false,
        Some(t) => {
            if t == "dumb" {
                return false;
            }
        }
    }
    env::var_os("NO_COLOR").is_none()
}

pub fn init() {
    let mut directives = Vec::new();
    let mut regex = None;
    if let Ok(spec) = env::var("RUST_LOG") {
        let (d, r) = parse_spec(&spec);
        directives = d;
        regex = r;
    }
    let logger = Logger {
        directives: build_directives(directives),
        regex,
        color: colors_allowed(),
    };
    let _ = LOGGER.set(logger);
}

impl Logger {
    fn enabled(&self, level: Level, target: &str) -> bool {
        for d in self.directives.iter().rev() {
            match d.name {
                Some(ref name) if !target.starts_with(name.as_str()) => {}
                _ => return (level as usize) <= (d.level as usize),
            }
        }
        false
    }

    fn log(&self, level: Level, msg: &str) {
        if !self.enabled(level, TARGET) {
            return;
        }
        if let Some(ref re) = self.regex {
            if !re.is_match(msg) {
                return;
            }
        }
        let (name, color) = match level {
            Level::Trace => ("TRACE", "35"),
            Level::Debug => ("DEBUG", "34"),
            Level::Info => (" INFO", "32"),
            Level::Warn => (" WARN", "33"),
            Level::Error => ("ERROR", "31"),
        };
        let line = if self.color {
            format!(
                " \x1b[0m\x1b[{}m{}\x1b[0m \x1b[0m\x1b[1m{}\x1b[0m > {}\n",
                color, name, TARGET, msg
            )
        } else {
            format!(" {} {} > {}\n", name, TARGET, msg)
        };
        let stderr = io::stderr();
        let mut handle = stderr.lock();
        let _ = handle.write_all(line.as_bytes());
        let _ = handle.flush();
    }
}

pub fn log(level: Level, msg: &str) {
    if let Some(logger) = LOGGER.get() {
        logger.log(level, msg);
    }
}

#[macro_export]
macro_rules! debug {
    ($($arg:tt)*) => {
        $crate::logger::log($crate::logger::Level::Debug, &format!($($arg)*))
    };
}

#[macro_export]
macro_rules! error {
    ($($arg:tt)*) => {
        $crate::logger::log($crate::logger::Level::Error, &format!($($arg)*))
    };
}
EOF"}

