//! Handling of the on-disk configuration file.

use std::env;
use std::ffi::{CStr, OsString};
use std::fs;
use std::io;
use std::os::unix::ffi::OsStringExt;
use std::path::PathBuf;

use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Default, Debug)]
struct Config {
    repo: PathBuf,
}

fn passwd_home() -> Option<PathBuf> {
    unsafe {
        let mut buf_len = match libc::sysconf(libc::_SC_GETPW_R_SIZE_MAX) {
            n if n < 0 => 512_usize,
            n => n as usize,
        };
        loop {
            let mut buf: Vec<libc::c_char> = Vec::with_capacity(buf_len);
            let mut passwd: libc::passwd = std::mem::zeroed();
            let mut result: *mut libc::passwd = std::ptr::null_mut();
            let rc = libc::getpwuid_r(
                libc::getuid(),
                &mut passwd,
                buf.as_mut_ptr(),
                buf_len,
                &mut result,
            );
            if rc == libc::ERANGE {
                buf_len *= 2;
                continue;
            }
            if rc != 0 || result.is_null() || passwd.pw_dir.is_null() {
                return None;
            }
            let bytes = CStr::from_ptr(passwd.pw_dir).to_bytes().to_vec();
            return Some(PathBuf::from(OsString::from_vec(bytes)));
        }
    }
}

fn home_dir() -> Option<PathBuf> {
    match env::var_os("HOME") {
        Some(h) if !h.is_empty() => Some(PathBuf::from(h)),
        _ => passwd_home(),
    }
}

pub struct FileHandler {
    dir: PathBuf,
    file: PathBuf,
}

impl FileHandler {
    pub fn new() -> FileHandler {
        let base = match env::var_os("XDG_CONFIG_HOME") {
            Some(x) => PathBuf::from(x),
            None => home_dir()
                .expect("Could not determine home directory")
                .join(".config"),
        };
        let dir = base.join("eureka");
        let file = dir.join("config.json");
        FileHandler { dir, file }
    }

    pub fn config_dir_exists(&self) -> bool {
        self.dir.exists()
    }

    pub fn create_config_dir(&self) -> io::Result<()> {
        fs::create_dir_all(&self.dir)
    }

    pub fn read_repo(&self) -> io::Result<String> {
        let contents = fs::read_to_string(&self.file)?;
        if contents.is_empty() {
            return Ok(String::new());
        }
        let config: Config = serde_json::from_str(&contents)?;
        Ok(config.repo.to_string_lossy().into_owned())
    }

    pub fn write_repo(&self, repo: &str) -> io::Result<()> {
        let config = Config {
            repo: PathBuf::from(repo),
        };
        let json = serde_json::to_string(&config)?;
        fs::write(&self.file, json)
    }

    pub fn remove_config(&self) -> io::Result<()> {
        fs::remove_file(&self.file)
    }
}
EOF"}

