//! Colored output and line based input.

use std::io::{self, BufRead, Write};

const RESET: &str = "\x1b[0m";
const BOLD: &str = "\x1b[1m";
const YELLOW: &str = "\x1b[33m";
const GREEN: &str = "\x1b[32m";

const FTS_BANNER: &str = "############################################################
####                  First Time Setup                  ####
############################################################

This tool requires you to have a repository with a README.md
in the root folder. The markdown file is where your ideas
will be stored.

Once first time setup has completed, simply run Eureka again
to begin writing down ideas.
        ";

pub struct Printer {
    out: io::Stdout,
}

impl Printer {
    pub fn new() -> Printer {
        Printer { out: io::stdout() }
    }

    pub fn print(&mut self, text: &str) -> io::Result<()> {
        writeln!(self.out, "{}", text)
    }

    pub fn print_fts_banner(&mut self) -> io::Result<()> {
        self.out.write_all(RESET.as_bytes())?;
        self.out.write_all(YELLOW.as_bytes())?;
        writeln!(self.out, "{}", FTS_BANNER)?;
        self.out.write_all(RESET.as_bytes())?;
        Ok(())
    }

    pub fn input_header(&mut self, text: &str) -> io::Result<()> {
        self.out.write_all(RESET.as_bytes())?;
        self.out.write_all(BOLD.as_bytes())?;
        self.out.write_all(GREEN.as_bytes())?;
        writeln!(self.out, "{}", text)?;
        self.out.write_all(RESET.as_bytes())?;
        write!(self.out, "> ")?;
        self.out.flush()
    }
}

pub struct Reader {
    input: io::Stdin,
}

impl Reader {
    pub fn new() -> Reader {
        Reader { input: io::stdin() }
    }

    pub fn read_input(&mut self) -> io::Result<String> {
        let mut line = String::new();
        self.input.lock().read_line(&mut line)?;
        Ok(line.trim().to_string())
    }
}
