//! Git operations on the ideas repository.

use std::path::Path;

use git2::{
    BranchType, Cred, CredentialType, Error, PushOptions, RemoteCallbacks, Repository,
};

pub struct Git {
    repo: Repository,
}

impl Git {
    pub fn open(path: &str) -> Result<Git, Error> {
        let repo = Repository::open(path)?;
        Ok(Git { repo })
    }

    pub fn checkout_branch(&self, name: &str) -> Result<(), Error> {
        let head = self.repo.head()?;
        let head_commit = head.peel_to_commit()?;
        if self.repo.find_branch(name, BranchType::Local).is_err() {
            self.repo.branch(name, &head_commit, false)?;
        }
        let refname = format!("refs/heads/{}", name);
        let target = self.repo.revparse_single(&refname)?;
        self.repo.checkout_tree(&target, None)?;
        self.repo.set_head(&refname)?;
        Ok(())
    }

    pub fn add(&self) -> Result<(), Error> {
        let mut index = self.repo.index()?;
        index.add_path(Path::new("README.md"))?;
        index.write()?;
        Ok(())
    }

    pub fn commit(&self, message: &str) -> Result<(), Error> {
        let mut index = self.repo.index()?;
        let tree_id = index.write_tree()?;
        let tree = self.repo.find_tree(tree_id)?;
        let signature = self.repo.signature()?;
        let parent = self.repo.head()?.peel_to_commit()?;
        self.repo.commit(
            Some("HEAD"),
            &signature,
            &signature,
            message,
            &tree,
            &[&parent],
        )?;
        Ok(())
    }

    pub fn push(&self, branch: &str) -> Result<(), Error> {
        let mut remote = self.repo.find_remote("origin")?;
        let config = self.repo.config()?;

        let mut tried_agent = false;
        let mut tried_helper = false;
        let mut callbacks = RemoteCallbacks::new();
        callbacks.credentials(move |url, username, allowed| {
            if allowed.contains(CredentialType::USERNAME) {
                if let Some(user) = username {
                    return Cred::username(user);
                }
            }
            if allowed.contains(CredentialType::SSH_KEY) && !tried_agent {
                tried_agent = true;
                let user = username.unwrap_or("git");
                return Cred::ssh_key_from_agent(user);
            }
            if allowed.contains(CredentialType::USER_PASS_PLAINTEXT) && !tried_helper {
                tried_helper = true;
                return Cred::credential_helper(&config, url, username);
            }
            Err(Error::from_str("No authentication method succeeded"))
        });

        let mut options = PushOptions::new();
        options.remote_callbacks(callbacks);
        let refspec = format!("refs/heads/{0}:refs/heads/{0}", branch);
        remote.push(&[refspec.as_str()], Some(&mut options))?;
        Ok(())
    }
}
