import os, subprocess, shutil, sys, json

ORIG = '/workspace/executable'
MINE = '/tmp/mine/executable'
ROOT = '/tmp/cmpenv'

def sh(cmd, cwd=None):
    subprocess.run(cmd, shell=True, cwd=cwd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def mkrepo(path, branch='master', readme='# Ideas\n', user=True, commit=True, remote=None):
    os.makedirs(path, exist_ok=True)
    sh(f'git init -q -b {branch}', cwd=path)
    if user:
        sh('git config user.email a@b.c && git config user.name tester', cwd=path)
    if readme is not None:
        open(os.path.join(path, 'README.md'), 'w').write(readme)
    if commit:
        sh('git add -A && git -c user.name=x -c user.email=y commit -qm init', cwd=path)
    if remote:
        sh(f'git remote add origin {remote}', cwd=path)

def cfg(home, repo):
    d = os.path.join(home, '.config', 'eureka')
    os.makedirs(d, exist_ok=True)
    open(os.path.join(d, 'config.json'), 'w').write(json.dumps({'repo': repo}, separators=(',', ':')))

def snapshot():
    out = []
    for dp, dn, fn in sorted(os.walk(ROOT)):
        dn.sort()
        if '/.git' in dp + '/' and ('/objects' in dp):
            continue
        for f in sorted(fn):
            p = os.path.join(dp, f)
            rel = os.path.relpath(p, ROOT)
            if '/.git/' in '/' + rel and (rel.endswith('index') or '/objects/' in rel or '/logs/' in rel):
                continue
            if '/.git/refs/' in '/' + rel or rel.endswith('ORIG_HEAD'):
                continue
            try:
                if os.path.islink(p):
                    out.append((rel, 'LINK->' + os.readlink(p)))
                else:
                    out.append((rel, open(p, 'rb').read()[:2000]))
            except Exception as e:
                out.append((rel, 'ERR ' + str(e)))
    # git state
    for dp, dn, fn in sorted(os.walk(ROOT)):
        if '.git' in dn or (dp.endswith('.git') and 'HEAD' in fn and 'objects' in dn):
            gitdir = dp if dp.endswith('.git') or 'objects' in dn and not '.git' in dn else os.path.join(dp, '.git')
