/// Rewrites a few libgit2 messages into the wording used by the libgit2
/// release this tool historically shipped with.
fn normalize_message(message: &str) -> String {
    const REWRITES: &[(&str, &str)] = &[(
        "could not find repository at '",
        "could not find repository from '",
    )];
    let mut msg = message.to_string();
    for (from, to) in REWRITES {
        if msg.starts_with(from) {
            msg = format!("{}{}", to, &msg[from.len()..]);
        }
    }
    msg
}

/// Formats a git error the same way `git2::Error`'s `Display` does, after
/// normalizing the message.
pub fn describe_error(e: &Error) -> String {
    use git2::{ErrorClass, ErrorCode};
    let mut out = normalize_message(e.message());
    if e.class() != ErrorClass::None {
        out.push_str(&format!("; class={:?} ({})", e.class(), e.raw_class()));
    }
    if e.code() != ErrorCode::GenericError {
        out.push_str(&format!("; code={:?} ({})", e.code(), e.raw_code()));
    }
    out
}
