//! Network transport shims.
//!
//! The bundled libgit2 is built without TLS and SSH support.  To still give
//! meaningful (and consistent) diagnostics when pushing to `https://` or SSH
//! remotes, a custom TLS stream and a custom SSH transport are registered.
//! Both resolve and connect to the remote host exactly like libgit2's socket
//! stream does, reporting resolution and connection failures with the same
//! wording.  Since no TLS/SSH implementation is available, an established
//! connection is reported as a handshake failure.

use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_uint, c_void};
use std::ptr;

use git2::transport::{Service, SmartSubtransport, SmartSubtransportStream, Transport};
use git2::{Error, ErrorClass, ErrorCode};

/// Resolves `host` and connects to `port`, mirroring libgit2's socket stream.
fn connect_host(host: &str, port: &str) -> Result<c_int, Error> {
    let c_host = CString::new(host).map_err(|_| Error::from_str("invalid host"))?;
    let c_port = CString::new(port).map_err(|_| Error::from_str("invalid port"))?;

    unsafe {
        let mut hints: libc::addrinfo = std::mem::zeroed();
        hints.ai_socktype = libc::SOCK_STREAM;
        hints.ai_family = libc::AF_UNSPEC;
        let mut info: *mut libc::addrinfo = ptr::null_mut();

        let rc = libc::getaddrinfo(c_host.as_ptr(), c_port.as_ptr(), &hints, &mut info);
        if rc != 0 {
            let reason = CStr::from_ptr(libc::gai_strerror(rc)).to_string_lossy();
            return Err(Error::new(
                ErrorCode::GenericError,
                ErrorClass::Net,
                format!("failed to resolve address for {}: {}", host, reason),
            ));
        }

        let mut sock: c_int = -1;
        let mut p = info;
        while !p.is_null() {
            let ai = &*p;
            let s = libc::socket(ai.ai_family, ai.ai_socktype | libc::SOCK_CLOEXEC, ai.ai_protocol);
            if s >= 0 {
                if libc::connect(s, ai.ai_addr, ai.ai_addrlen) == 0 {
                    sock = s;
                    break;
                }
                let saved = *libc::__errno_location();
                libc::close(s);
                *libc::__errno_location() = saved;
            }
            p = ai.ai_next;
        }
        let errno = *libc::__errno_location();
        libc::freeaddrinfo(info);

        if sock < 0 {
            let mut msg = format!("failed to connect to {}", host);
            if errno != 0 {
                let reason = CStr::from_ptr(libc::strerror(errno)).to_string_lossy();
                msg.push_str(": ");
                msg.push_str(&reason);
            }
            return Err(Error::new(ErrorCode::GenericError, ErrorClass::Os, msg));
        }
        Ok(sock)
    }
}

// ---------------------------------------------------------------------------
// TLS stream
// ---------------------------------------------------------------------------

#[repr(C)]
struct RawStream {
    version: c_int,
    flags: c_uint,
    timeout: c_int,
    connect_timeout: c_int,
    connect: Option<unsafe extern "C" fn(*mut RawStream) -> c_int>,
    certificate: Option<unsafe extern "C" fn(*mut *mut c_void, *mut RawStream) -> c_int>,
    set_proxy: Option<unsafe extern "C" fn(*mut RawStream, *const c_void) -> c_int>,
    read: Option<unsafe extern "C" fn(*mut RawStream, *mut c_void, usize) -> isize>,
    write: Option<unsafe extern "C" fn(*mut RawStream, *const c_char, usize, c_int) -> isize>,
    close: Option<unsafe extern "C" fn(*mut RawStream) -> c_int>,
    free: Option<unsafe extern "C" fn(*mut RawStream)>,
}

#[repr(C)]
struct TlsStream {
    raw: RawStream,
    host: String,
    port: String,
    fd: c_int,
}

#[repr(C)]
struct StreamRegistration {
    version: c_int,
    init: Option<unsafe extern "C" fn(*mut *mut RawStream, *const c_char, *const c_char) -> c_int>,
    wrap: Option<unsafe extern "C" fn(*mut *mut RawStream, *mut RawStream, *const c_char) -> c_int>,
}

const GIT_STREAM_TLS: c_int = 2;

extern "C" {
    fn git_stream_register(kind: c_int, registration: *mut StreamRegistration) -> c_int;
}

fn set_git_error(e: &Error) -> c_int {
    let msg = CString::new(e.message()).unwrap_or_default();
    unsafe {
        libgit2_sys::git_error_set_str(e.raw_class(), msg.as_ptr());
    }
    e.raw_code()
}

unsafe extern "C" fn tls_connect(stream: *mut RawStream) -> c_int {
    let st = &mut *(stream as *mut TlsStream);
    match connect_host(&st.host, &st.port) {
        Ok(fd) => {
            st.fd = fd;
            let e = Error::new(ErrorCode::GenericError, ErrorClass::Ssl, "SSL error: unknown error");
            set_git_error(&e)
        }
        Err(e) => set_git_error(&e),
    }
}

unsafe extern "C" fn tls_certificate(_out: *mut *mut c_void, _stream: *mut RawStream) -> c_int {
    let e = Error::new(ErrorCode::GenericError, ErrorClass::Ssl, "SSL error: unknown error");
    set_git_error(&e)
}

unsafe extern "C" fn tls_set_proxy(_stream: *mut RawStream, _opts: *const c_void) -> c_int {
    0
}

unsafe extern "C" fn tls_read(_stream: *mut RawStream, _buf: *mut c_void, _len: usize) -> isize {
    let e = Error::new(ErrorCode::GenericError, ErrorClass::Ssl, "SSL error: unknown error");
    set_git_error(&e);
    -1
}

unsafe extern "C" fn tls_write(_stream: *mut RawStream, _buf: *const c_char, _len: usize, _flags: c_int) -> isize {
    let e = Error::new(ErrorCode::GenericError, ErrorClass::Ssl, "SSL error: unknown error");
    set_git_error(&e);
    -1
}

unsafe extern "C" fn tls_close(stream: *mut RawStream) -> c_int {
    let st = &mut *(stream as *mut TlsStream);
    if st.fd >= 0 {
        libc::close(st.fd);
        st.fd = -1;
    }
    0
}

unsafe extern "C" fn tls_free(stream: *mut RawStream) {
    if stream.is_null() {
        return;
    }
    tls_close(stream);
    drop(Box::from_raw(stream as *mut TlsStream));
}

unsafe extern "C" fn tls_init(out: *mut *mut RawStream, host: *const c_char, port: *const c_char) -> c_int {
    let host = if host.is_null() { String::new() } else { CStr::from_ptr(host).to_string_lossy().into_owned() };
    let port = if port.is_null() { String::new() } else { CStr::from_ptr(port).to_string_lossy().into_owned() };
    let stream = Box::new(TlsStream {
        raw: RawStream {
            version: 1,
            flags: 1, // encrypted
            timeout: 0,
            connect_timeout: 0,
            connect: Some(tls_connect),
            certificate: Some(tls_certificate),
            set_proxy: Some(tls_set_proxy),
            read: Some(tls_read),
            write: Some(tls_write),
            close: Some(tls_close),
            free: Some(tls_free),
        },
        host,
        port,
        fd: -1,
    });
    *out = Box::into_raw(stream) as *mut RawStream;
    0
}

