/// Registers the TLS stream and SSH transports.  Safe to call once.
pub fn install() {
    libgit2_sys::init();
    unsafe {
        let mut registration = StreamRegistration {
            version: 1,
            init: Some(tls_init),
            wrap: None,
        };
        git_stream_register(GIT_STREAM_TLS, &mut registration);

        for scheme in ["ssh", "ssh+git", "git+ssh"] {
            let _ = git2::transport::register(scheme, |remote| {
                Transport::smart(remote, false, SshSubtransport)
            });
        }

        let agent = CString::new("libgit2 1.5.1").unwrap();
        libgit2_sys::git_libgit2_opts(libgit2_sys::GIT_OPT_SET_USER_AGENT as c_int, agent.as_ptr());
    }
}
